def reuse_score(count, succ):
    # count: 片段规范化后的出现次数; succ: 该片段所在轨迹的平均成功率
    return count * succ

def should_merge(count_a, succ_a, count_b, succ_b, tau):
    merged = reuse_score(count_a + count_b, (succ_a + succ_b) / 2)
    return merged >= tau

def adaptive_advantage(A_t, node_reuse_scores, lam=0.1):
    # node_reuse_scores: 覆盖该 token 的 X-Tree 节点的可复用性分数列表
    return A_t + lam * sum(node_reuse_scores)

import torch

def fkl(logp_t, logq_s):
    return (logp_t.exp() * (logp_t - logq_s)).sum(-1).mean()

def rkl(logp_t, logq_s):
    return (logq_s.exp() * (logq_s - logp_t)).sum(-1).mean()

import torch

def mixed_rollout_logp(student_logp, teacher_logp, alpha):
    # 按 alpha 插值两个分布再取对数，alpha=1 全学生、alpha=0 全教师
    mix = alpha * student_logp.exp() + (1 - alpha) * teacher_logp.exp()
    return torch.log(mix + 1e-12)

import torch
import torch.nn.functional as F

def selective_distill(student_logits, teacher_logits, selected_idx, lam=0.5):
    s = F.log_softmax(student_logits[selected_idx], dim=-1)
    t = F.softmax(teacher_logits[selected_idx], dim=-1)
    return lam * F.kl_div(s, t, reduction='batchmean')

import torch

def effective_rank(delta_W, eps=1e-3):
    s = torch.linalg.svdvals(delta_W)
    return int((s > eps * s.max()).sum())
